  function saveKnowledge(){try{localStorage.setItem(key,JSON.stringify(knowledge));return true}catch{toast('브라우저 저장 공간을 사용할 수 없어요. 현재 화면에서만 변경됩니다.');return false}}
  function setPanel(panel){currentPanel=panel;document.querySelectorAll('.view').forEach(v=>v.classList.add('hidden'));byId(panel+'View').classList.remove('hidden');document.body.classList.add('assistant-mode');document.querySelectorAll('.nav-item').forEach(n=>n.classList.remove('active'));byId(panel+'Nav').classList.add('active');byId('pageName').textContent=panel==='assistant'?'어시스턴트':'공유 지식';byId('heading').textContent=panel==='assistant'?'혼자 하던 일을, 함께.':'쌓이는 경험이 팀의 자산이 되도록.';byId('subheading').textContent=panel==='assistant'?'대화하고, 준비하고, 팀의 지식으로 남기세요.':'용어와 관계를 정리하고, 확인한 지식을 함께 사용하세요.';if(panel==='knowledge')renderKnowledge();updateContext();}
  document.querySelectorAll('.nav-item[data-view]').forEach(n=>n.addEventListener('click',()=>document.body.classList.remove('assistant-mode')));
